from typing import List

def max_pyramid_size(A: List[int]) -> int:
    start, end = 0, len(A) - 1
    max_size = 0

    while start <= end:
        potential_height = min(A[start], A[end])
        current_size = potential_height * 2 - 1

        if A[start] < A[end]:
            start += 1
        else:
            end -= 1

        max_size = max(max_size, current_size)

    return max_size
